typedef float time_value_t;

bool TIMER_IsInfiniteDuration();

class IGOWidget
{
protected:
	bool display;
public:
	virtual ~IGOWidget();
	virtual void SetDisplay(const bool);
	virtual void Update(const float);
	virtual void Draw(void);
};

class PanelQuad
{
public:
	virtual ~PanelQuad();
	virtual void Init(float, float, float, float, float, float, float, float, float, float, float, float, float, void *);
	virtual void TurnOn(bool);
	virtual void SetLayer(int);
	virtual void Rotate(float);
	virtual void Rotate(float, float, float);
	virtual void Update(time_value_t);
	virtual void Draw(int = 0, float = -1.0f);
};

class PanelQuad4 : public PanelQuad
{
};

class TextString
{
public:
	virtual ~TextString();
	virtual void Update(time_value_t);
	virtual void Draw();
};

class AnalogClockWidget : public IGOWidget
{
private:
	enum { MAX_TIME_SEGMENTS = 60 };
	int clockMin;
	float clockSec;
	float elapsedInterval;
	PanelQuad *clockHandPQ;
	PanelQuad *clockFramePQ;
	PanelQuad *clockFacePQ;
	PanelQuad *num1PQ;
	PanelQuad *num2PQ;
	PanelQuad *num3PQ;
	PanelQuad *num4PQ;
	PanelQuad *num5PQ;
	PanelQuad *infPQ;
	PanelQuad4 *timeSegs[MAX_TIME_SEGMENTS];
	float handCenterX, handCenterY;
	int score;
	TextString *scoreText;
public:
	virtual ~AnalogClockWidget();
	virtual void SetDisplay(const bool);
	virtual void Init(void *, void *);
	virtual void Update(const float);
	virtual void Draw(void);
	virtual void SetScore(const int);
	virtual void ShowElapsedTime(const float);
	virtual void HideElapsedTime(void);
};

void AnalogClockWidget::Draw(void)
{
	int i;

	IGOWidget::Draw();

	if (!display)
		return;

	if (!TIMER_IsInfiniteDuration())
	{
		num1PQ->Draw(0);
		num2PQ->Draw(0);
		num3PQ->Draw(0);
		num4PQ->Draw(0);
		num5PQ->Draw(0);
	}
	else
		infPQ->Draw(0);

	clockFramePQ->Draw(0);
	clockFacePQ->Draw(0);
	if (!TIMER_IsInfiniteDuration())
		clockHandPQ->Draw(0);

	for (i = 0; i<MAX_TIME_SEGMENTS; i++)
	{
		timeSegs[i]->Draw(0);
	}

	scoreText->Draw();
}
